# Try grouping objects to left side
def move_objects_left(grid):
    new_grid = [[0]*11 for _ in range(11)]
    items = []
    for r in range(11):
        for c in range(11):
            if grid[r][c] != 0:
                items.append((grid[r][c], r, c))

    # Pack to left side, maintaining row order
    ptr = 0
    for r in range(11):
        for col in range(11):
            if ptr < len(items):
                new_grid[r][col] = items[ptr][0]
                ptr += 1
            else:
                break

    return new_grid

